package dev.kubejseditor.recipe.compat;

import com.google.gson.*;
import java.math.BigDecimal;
import java.util.*;
import static dev.kubejseditor.recipe.compat.CompatDefinition.*;

/** One document can have many visual occurrences. Views never own native inventory stacks. */
public class RecipePresentation {
    public final JsonObject data;public final CompatDefinition definition;
    public RecipePresentation(JsonObject data,CompatDefinition definition){this.data=data;this.definition=definition;definition.check();}
    public record Binding(Field field,String path,int occurrence){public String key(){return path+"@"+occurrence;}public boolean output(){return field.role==Role.OUTPUT;}public boolean fluid(){return field.kind==Kind.FLUID;}}
    public List<Binding> editableBindings(){var out=new ArrayList<>(bindings().stream().filter(b->!nativeValue(b).isJsonNull()||b.field.required||b.field.fallback!=null).toList());for(var f:definition.fields)if(f.list&&f.slot())out.add(new Binding(f,f.path+"/-",0));return out;}
    public void appendItem(Field field,JsonObject value){JsonElement template=field.template;var current=CompatJson.get(data,field.path);if(current.isJsonArray()&&!current.getAsJsonArray().isEmpty())template=current.getAsJsonArray().get(0).deepCopy();if(template==null){if(!Set.of("modern_industrialization","forbidden_arcanus","ars_nouveau").contains(definition.source))throw new IllegalArgumentException("空列表需要先在映射定义中确认原生条目 template");if(field.role==Role.CATALYST)template=new JsonPrimitive("forbidden_arcanus:artisan_relic");else{var o=new JsonObject();if(!field.expand.isBlank()){var ingredient=new JsonObject();ingredient.addProperty("item","minecraft:stone");o.add("ingredient",ingredient);o.addProperty(field.expand,1);}else{o.addProperty(field.kind==Kind.FLUID?"fluid":"item",field.kind==Kind.FLUID?"minecraft:water":"minecraft:stone");if(!field.quantity.isBlank())o.addProperty(field.quantity,1);}template=o;}}
        var snapshot=data.deepCopy();try{if(!field.expand.isBlank()){template=template.deepCopy();template.getAsJsonObject().addProperty(field.expand,1);}append(field,template);var array=CompatJson.get(data,field.path).getAsJsonArray();writeItem(new Binding(field,field.path+"/"+(array.size()-1),0),value);}catch(RuntimeException e){data.entrySet().clear();snapshot.entrySet().forEach(e2->data.add(e2.getKey(),e2.getValue()));throw e;}}
    public List<Binding> bindings(){var out=new ArrayList<Binding>();for(var f:definition.fields){if(!f.list){out.add(new Binding(f,f.path,0));continue;}var a=CompatJson.get(data,f.path);if(!a.isJsonArray())continue;for(int i=0;i<a.getAsJsonArray().size();i++){var v=a.getAsJsonArray().get(i);int n=f.expand.isBlank()?1:positive(v.getAsJsonObject().get(f.expand));if(n>256)throw new IllegalArgumentException("展开槽位过多："+f.path);for(int j=0;j<n;j++)out.add(new Binding(f,f.path+"/"+i,j));}}return out;}
    private static int positive(JsonElement n){if(n==null)return 1;int v=n.getAsBigDecimal().intValueExact();if(v<1)throw new IllegalArgumentException("数量必须为正整数");return v;}
    public JsonElement nativeValue(Binding b){var v=CompatJson.get(data,b.path);return v.isJsonNull()&&b.field.fallback!=null?b.field.fallback.deepCopy():v.deepCopy();}
    public JsonObject item(Binding b){JsonElement v=nativeValue(b);var f=b.field;if(!f.expand.isBlank())v=v.getAsJsonObject().get("ingredient");JsonObject result;
        if(!f.valuePath.isBlank()){var raw=v;v=CompatJson.get(raw,f.valuePath);result=canonical(v,b);var quantity=f.quantity.isBlank()?JsonNull.INSTANCE:CompatJson.get(raw,f.quantityPath.isBlank()?"/"+CompatJson.escape(f.quantity):f.quantityPath);if(!quantity.isJsonNull())result.add(b.fluid()?"amount":"count",quantity);if(!f.probability.isBlank()){var chance=CompatJson.get(raw,"/"+CompatJson.escape(f.probability));result.add("chance",chance.isJsonNull()?new JsonPrimitive(1):chance);}return result;}
        if(nestedStack(v)){result=dev.kubejseditor.recipe.SimpleRecipeAdapter.Format.inspect(v,b.output(),b.fluid()).read(v);if(!result.has("count"))result.addProperty("count",1);if(!f.probability.isBlank()&&!result.has("chance"))result.addProperty("chance",1);return result;}
        if(v.isJsonPrimitive()){result=new JsonObject();String id=v.getAsString();result.addProperty(id.startsWith("#")?"tag":b.output()?"id":b.fluid()?"fluid":"item",id.startsWith("#")?id.substring(1):id);}
        else if(v.isJsonArray()){result=new JsonObject();result.add("alternatives",v.deepCopy());}
        else {result=v.getAsJsonObject().deepCopy();if(result.has("ingredient")){var wrapper=result;var ingredient=wrapper.get("ingredient");if(ingredient.isJsonArray()){result=new JsonObject();result.add("alternatives",ingredient.deepCopy());}else result=ingredient.getAsJsonObject().deepCopy();if(!f.quantity.isBlank()&&wrapper.has(f.quantity))result.add(b.fluid()?"amount":"count",wrapper.get(f.quantity));}else{if(result.has("item")&&b.output()){result.add("id",result.remove("item"));}if(!b.fluid()&&!f.quantity.isBlank()&&!f.quantity.equals("count")&&result.has(f.quantity)){result.add("count",result.remove(f.quantity));}}}
        if(f.quantity.isBlank()&&result.has("count")&&result.get("count").getAsInt()==0)result.addProperty("count",1);
        if(result.has("type")&&result.get("type").getAsString().equals("neoforge:components")&&!result.has("strict"))result.addProperty("strict",false);
        if(!f.expand.isBlank())result.addProperty("count",1);
        result=normalizeOr(result);if(!result.has(b.fluid()?"amount":"count"))result.addProperty(b.fluid()?"amount":"count",1);
        var nativeEntry=nativeValue(b);if(!f.probability.isBlank())result.remove(f.probability);if(!f.probability.isBlank())result.add("chance",nativeEntry.isJsonObject()&&nativeEntry.getAsJsonObject().has(f.probability)?nativeEntry.getAsJsonObject().get(f.probability):new JsonPrimitive(1));return result;
    }
    public void writeItem(Binding b,JsonObject edit){var f=b.field;if(f.quantity.isBlank()&&edit.has("count")&&positive(edit.get("count"))!=1)throw new IllegalArgumentException("此字段的单格数量固定为 1");
        if(!f.readOnlyReason.isBlank())throw new IllegalArgumentException(f.readOnlyReason);
        if(!f.valuePath.isBlank()){var raw=nativeValue(b).getAsJsonObject();CompatJson.set(raw,f.valuePath,writeIdentity(CompatJson.get(raw,f.valuePath),edit,f,false));if(!f.quantity.isBlank())CompatJson.set(raw,f.quantityPath.isBlank()?"/"+CompatJson.escape(f.quantity):f.quantityPath,edit.has(b.fluid()?"amount":"count")?edit.get(b.fluid()?"amount":"count"):new JsonPrimitive(1));if(!f.probability.isBlank()&&edit.has("chance"))raw.add(f.probability,edit.get("chance"));CompatJson.set(data,b.path,raw);return;}
        if(nestedStack(nativeValue(b))){var old=nativeValue(b);if(!f.probability.isBlank()&&edit.has("chance"))old.getAsJsonObject().add(f.probability,edit.get("chance"));CompatJson.set(data,b.path,dev.kubejseditor.recipe.SimpleRecipeAdapter.Format.inspect(old,b.output(),b.fluid()).write(old,edit));return;}
        if(!f.expand.isBlank()){var expanded=expanded(f);int index=expandedIndex(b);var old=expanded.get(index).getAsJsonObject();old.add("ingredient",writeIdentity(old.get("ingredient"),edit,f,false));expanded.set(index,old);CompatJson.set(data,f.path,compact(expanded,f.expand));return;}
        JsonElement old=nativeValue(b);JsonElement next;
        if(old.isJsonPrimitive()){String id=identity(edit);if(edit.has("components")||edit.has("count")&&positive(edit.get("count"))!=1)throw new IllegalArgumentException("此字段仅接受物品类型，不接受数量或组件");next=new JsonPrimitive(edit.has("tag")?"#"+id:id);}
        else if(old.isJsonObject()&&old.getAsJsonObject().has("ingredient")){var o=old.getAsJsonObject();o.add("ingredient",writeIdentity(o.get("ingredient"),edit,f,false));if(!f.quantity.isBlank())o.add(f.quantity,edit.has(b.fluid()?"amount":"count")?edit.get(b.fluid()?"amount":"count"):new JsonPrimitive(1));next=o;}
        else next=writeIdentity(old,edit,f,true);
        if(next.isJsonObject()&&!f.probability.isBlank()&&edit.has("chance"))next.getAsJsonObject().add(f.probability,edit.get("chance"));CompatJson.set(data,b.path,next);
    }
    private static JsonObject canonical(JsonElement value,Binding binding){JsonObject result;if(value.isJsonArray()){result=new JsonObject();result.add("alternatives",value.deepCopy());}else if(value.isJsonPrimitive()){result=new JsonObject();String id=value.getAsString();result.addProperty(id.startsWith("#")?"tag":binding.output()?"id":binding.fluid()?"fluid":"item",id.startsWith("#")?id.substring(1):id);}else result=value.getAsJsonObject().deepCopy();if(result.has("type")&&result.get("type").getAsString().equals("neoforge:components")&&!result.has("strict"))result.addProperty("strict",false);if(!result.has(binding.fluid()?"amount":"count"))result.addProperty(binding.fluid()?"amount":"count",1);return normalizeOr(result);}
    public JsonArray alternatives(Binding b){var value=item(b);if(value.has("alternatives"))return value.getAsJsonArray("alternatives").deepCopy();value.remove("count");value.remove("amount");value.remove("chance");var out=new JsonArray();out.add(value);return out;}
    public void writeAlternatives(Binding b,JsonArray candidates){if(b.output()||b.field.kind!=Kind.ITEM||candidates.isEmpty())throw new IllegalArgumentException("OR 仅用于物品输入，至少保留一个候选");if(b.field.valuePath.isBlank()&&(!b.field.quantity.isBlank()||nativeValue(b).isJsonPrimitive()))throw new IllegalArgumentException("此原生包装未声明 OR 写入格式，可在高级模式查看原始结构");var edit=item(b);edit.add("alternatives",candidates.deepCopy());writeItem(b,edit);}
    public void writeOther(Binding b,JsonElement encoded){if(b.field.kind!=Kind.OTHER||!b.field.readOnlyReason.isBlank())throw new IllegalArgumentException("此原料没有有效写入编码");if(b.field.valuePath.isBlank())CompatJson.set(data,b.path,encoded);else{var raw=nativeValue(b).getAsJsonObject();CompatJson.set(raw,b.field.valuePath,encoded);CompatJson.set(data,b.path,raw);}}
    private static JsonObject normalizeOr(JsonObject value){if(value.has("type")&&value.get("type").isJsonPrimitive()&&value.get("type").getAsString().equals("neoforge:compound")&&value.has("children")&&value.get("children").isJsonArray()){value=value.deepCopy();value.remove("type");value.add("alternatives",value.remove("children"));}return value;}
    private static String identity(JsonObject edit){if(edit.has("alternatives")&&edit.get("alternatives").isJsonArray()&&!edit.getAsJsonArray("alternatives").isEmpty())return "";for(String key:List.of("tag","items","id","item","fluid"))if(edit.has(key)&&edit.get(key).isJsonPrimitive()){String id=edit.get(key).getAsString();dev.kubejseditor.model.EditorProject.requireId(id.startsWith("#")?id.substring(1):id);return id;}if(edit.has("type")&&edit.get("type").isJsonPrimitive()){dev.kubejseditor.model.EditorProject.requireId(edit.get("type").getAsString());return "";}throw new IllegalArgumentException("请选择明确的物品、标签或流体");}
    private static JsonElement writeIdentity(JsonElement old,JsonObject edit,Field f,boolean quantities){identity(edit);if(edit.has("id")&&f.role!=Role.OUTPUT){edit=edit.deepCopy();edit.add("item",edit.remove("id"));}
        if(edit.has("alternatives"))return edit.get("alternatives").deepCopy();var result=old.isJsonObject()?old.getAsJsonObject().deepCopy():new JsonObject();String target=edit.has("tag")?"tag":edit.has("items")?"items":old.isJsonObject()&&old.getAsJsonObject().has("id")?"id":f.kind==Kind.FLUID?"fluid":"item";
        for(String key:List.of("id","item","fluid","tag","items"))result.remove(key);
        result.addProperty(target,identity(edit));
        if(edit.has("type")&&edit.get("type").getAsString().equals("neoforge:components")){result.addProperty("type","neoforge:components");if(edit.has("strict"))result.add("strict",edit.get("strict"));}
        else if(result.has("type")&&Set.of("neoforge:single","neoforge:tag","neoforge:components").contains(result.get("type").getAsString())){if(f.kind==Kind.FLUID)result.addProperty("type",target.equals("tag")?"neoforge:tag":"neoforge:single");else{result.remove("type");result.remove("strict");}}
        if(edit.has("components"))result.add("components",edit.get("components").deepCopy());else result.remove("components");
        if(quantities&&!f.quantity.isBlank())result.add(f.quantity,edit.has(f.kind==Kind.FLUID?"amount":"count")?edit.get(f.kind==Kind.FLUID?"amount":"count").deepCopy():new JsonPrimitive(1));return result;
    }
    private static boolean nestedStack(JsonElement value){return value.isJsonObject()&&List.of("item","result").stream().anyMatch(key->value.getAsJsonObject().has(key)&&value.getAsJsonObject().get(key).isJsonObject());}
    public void remove(Binding b){if(!b.field.list){if(!b.field.required){CompatJson.remove(data,b.path);return;}throw new IllegalArgumentException("必需字段不能清空");}if(!b.field.expand.isBlank()){var a=expanded(b.field);a.remove(expandedIndex(b));CompatJson.set(data,b.field.path,compact(a,b.field.expand));}else CompatJson.remove(data,b.path);}
    public void append(Field f,JsonElement entry){if(!f.list)throw new IllegalArgumentException("不是列表字段");var prior=CompatJson.get(data,f.path);var a=prior.isJsonArray()?prior.getAsJsonArray().deepCopy():new JsonArray();a.add(entry.deepCopy());CompatJson.set(data,f.path,a);}
    private JsonArray expanded(Field f){var a=new JsonArray();for(var entry:CompatJson.get(data,f.path).getAsJsonArray()){int n=positive(entry.getAsJsonObject().get(f.expand));for(int i=0;i<n;i++){var e=entry.getAsJsonObject().deepCopy();e.addProperty(f.expand,1);a.add(e);}}return a;}
    private int expandedIndex(Binding b){int index=Integer.parseInt(b.path.substring(b.path.lastIndexOf('/')+1)),n=b.occurrence;var a=CompatJson.get(data,b.field.path).getAsJsonArray();for(int i=0;i<index;i++)n+=positive(a.get(i).getAsJsonObject().get(b.field.expand));return n;}
    private static JsonArray compact(JsonArray array,String quantity){var out=new JsonArray();for(var v:array){var e=v.getAsJsonObject().deepCopy();if(!out.isEmpty()){var last=out.get(out.size()-1).getAsJsonObject();var a=last.deepCopy();var b=e.deepCopy();a.remove(quantity);b.remove(quantity);if(CompatJson.equal(a,b)){last.addProperty(quantity,positive(last.get(quantity))+positive(e.get(quantity)));continue;}}out.add(e);}return out;}
    public List<String> validate(){var errors=new ArrayList<String>();try{for(var b:bindings()){var f=b.field;JsonElement v=nativeValue(b);if(!f.readOnlyReason.isBlank())continue;if(v.isJsonNull()){if(f.required)errors.add("缺少字段："+b.path);continue;}if(f.slot()&&f.kind!=Kind.OTHER){var item=item(b);identity(item);var n=item.get(b.fluid()?"amount":"count");if(n.getAsBigDecimal().compareTo(BigDecimal.ONE)<0||n.getAsBigDecimal().stripTrailingZeros().scale()>0)errors.add("数量必须为正整数："+b.path);if(!f.probability.isBlank()&&item.has("chance")){var c=item.get("chance").getAsBigDecimal();if(c.signum()<0||c.compareTo(BigDecimal.ONE)>0)errors.add("概率必须在 0～1："+b.path);}}else if(f.kind==Kind.NUMBER){if(!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("需要数值："+b.path);var n=v.getAsBigDecimal();if(f.integer)n.toBigIntegerExact();if(f.role==Role.RESOURCE&&n.signum()<0)errors.add("资源不能为负："+b.path);}else if(f.kind==Kind.BOOLEAN&&(!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isBoolean()))errors.add("需要布尔值："+b.path);}
        if(CompatDefinitions.isRitual(definition.type)&&definition.fields.stream().anyMatch(f->!f.expand.isBlank())){long n=bindings().stream().filter(b->!b.field.expand.isBlank()).count();if(n<1||n>8)errors.add("外围基座总数必须为 1～8");}
    }catch(RuntimeException error){errors.add(error.getMessage()==null?error.toString():error.getMessage());}return errors;}
    public void verifyRoundTrip(JsonObject encoded){var actual=new RecipePresentation(encoded,definition);for(var b:bindings()){if(!b.field.readOnlyReason.isBlank())continue;if(nativeValue(b).isJsonNull()&&actual.nativeValue(b).isJsonNull())continue;JsonElement expected=b.field.slot()&&b.field.kind!=Kind.OTHER?item(b):nativeValue(b),found=b.field.slot()&&b.field.kind!=Kind.OTHER?actual.item(b):actual.nativeValue(b);if(!CompatJson.equal(expected,found))throw new IllegalArgumentException("原生 Codec 未保留修改："+b.path);}}
}
